  public class F_Role
  {
    public enum RoleType
    {
      AdminApp,
      Admin,
      Leader,
      User
    }

    public static RoleType GetRoleTypeFromString(string roleString)
    {
      return roleString.ToLower() switch
      {
        "adminapp" => RoleType.AdminApp,
        "admin" => RoleType.Admin,
        "leader" => RoleType.Leader,
        "user" => RoleType.User,
        _ => RoleType.User,
      };
    } 
  }
